class Solution:
    def largestLocal(self, grid: list[list[int]]) -> list[list[int]]:
        n = len(grid)
        res = [[0] * (n - 2) for _ in range(n - 2)]
        for r in range(n - 2):
            for c in range(n - 2):
                res[r][c] = max(grid[r + i][c + j] for i in range(3) for j in range(3))
        return res

class Solution {
public:
    std::vector<std::vector<int>> largestLocal(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        std::vector<std::vector<int>> res(n - 2, std::vector<int>(n - 2, 0));
        for (int r = 0; r < n - 2; ++r) {
            for (int c = 0; c < n - 2; ++c) {
                int mx = 0;
                for (int i = 0; i < 3; ++i) {
                    for (int j = 0; j < 3; ++j) {
                        mx = std::max(mx, grid[r + i][c + j]);
                    }
                }
                res[r][c] = mx;
            }
        }
        return res;
    }
};

class Solution {
    public int[][] largestLocal(int[][] grid) {
        int n = grid.length;
        int[][] res = new int[n - 2][n - 2];
        for (int r = 0; r < n - 2; ++r) {
            for (int c = 0; c < n - 2; ++c) {
                int mx = 0;
                for (int i = 0; i < 3; ++i) {
                    for (int j = 0; j < 3; ++j) {
                        mx = Math.max(mx, grid[r + i][c + j]);
                    }
                }
                res[r][c] = mx;
            }
        }
        return res;
    }
}

var largestLocal = function(grid) {
    const n = grid.length;
    const res = Array.from({ length: n - 2 }, () => new Array(n - 2).fill(0));
    for (let r = 0; r < n - 2; ++r) {
        for (let c = 0; c < n - 2; ++c) {
            let mx = 0;
            for (let i = 0; i < 3; ++i) {
                for (let j = 0; j < 3; ++j) {
                    if (grid[r + i][c + j] > mx) mx = grid[r + i][c + j];
                }
            }
            res[r][c] = mx;
        }
    }
    return res;
};
